   "fact": "杨万里(1127—1206),宋代诗人。字廷秀，号诚斋，南宋诗人，与陆游、尤袤、范成大并称「南宋四大家」。他自创「诚斋体」，诗风清新自然，语言通俗，想象丰富，充满生活情趣。代表作:《小池》《晓出净慈寺送林子方》《宿新市徐公店》。",
