   "fact": "李清照(1084—约1155),宋代诗人。号易安居士，宋代女词人，中国古代最杰出的女作家之一。她的词前期清新婉丽，多写闺阁生活；后期感伤悲凉，多抒亡国之痛。语言清丽典雅，音律和谐优美。代表作:《如梦令》《醉花阴》《声声慢》《一剪梅》。",
