   "fact": "陆游(1125—1210),宋代诗人。字务观，号放翁，南宋爱国诗人。他一生创作了近万首诗，是古代留下诗作最多的诗人之一。陆游始终坚守抗金救国理想，诗中充满壮志未酬的悲愤。代表作:《示儿》《游山西村》《十一月四日风雨大作》《卜算子·咏梅》。",
