   "fact": "苏轼(1037—1101),宋代诗人。字子瞻，号东坡居士，北宋文学家，唐宋八大家之一。他多才多艺，诗、词、文、书、画均有极高成就。苏轼性格旷达，屡遭贬谪而不改其志，词开豪放一派。代表作:《题西林壁》《饮湖上初晴后雨》《惠崇春江晚景》《水调歌头》《念奴娇》。",
   "type": "next",
   "q": "「白雨跳珠乱入船。」的下一句是?",
   "options": [
    "忧从中来，不可断绝。",
    "便引诗情到碧霄。",
    "卷地风来忽吹散，",
    "譬如朝露，去日苦多。"
   ],
   "answer": 2,
   "themes": [
    "nature"
   ]
