   "author": "杜甫",
   "fact": "杜甫(712—770),唐代诗人。字子美，自号少陵野老，唐代现实主义诗人，被誉为「诗圣」。他的诗深刻反映社会现实，表达忧国忧民的情怀。杜甫颠沛流离的一生使他的作品具有深厚的历史价值和人文精神。代表作:《春望》《茅屋为秋风所破歌》《望岳》《春夜喜雨》《绝句》。",
