   "fact": "韩愈(768—824),唐代诗人。字退之，唐代文学家、思想家，唐宋八大家之首。他倡导古文运动，主张「文以载道」。韩愈也是杰出诗人，其诗风雄奇险怪，与孟郊并称「韩孟诗派」。代表作:《早春呈水部张十八员外》《左迁至蓝关示侄孙湘》。",
   "type": "next",
