   "title": "后宫词",
   "author": "白居易",
   "fact": "白居易(772—846),唐代诗人。字乐天，号香山居士，唐代伟大的现实主义诗人。他的诗语言通俗易懂，风格平易近人，强调「文章合为时而著，歌诗合为事而作」。白居易与元稹并称「元白」，是新乐府运动的倡导者。代表作:《赋得古原草送别》《钱塘湖春行》《忆江南》《卖炭翁》《琵琶行》。",
