   "fact": "贺知章(659—744),唐代诗人。字季真，自号四明狂客，唐代著名诗人、书法家。性格豪放旷达，好饮酒，与李白、张旭等人友善。晚年辞官还乡，其诗清新通俗，《咏柳》《回乡偶书》最为著名。代表作:《咏柳》《回乡偶书》。",
   "type": "next",
   "q": "「少小离家老大回，乡音无改鬓毛衰。」的下一句是?",
   "options": [
    "石鱼湖，似洞庭，夏水欲满君山青。",
    "先拂商弦后角羽，四郊秋叶惊摵摵。",
    "渔舟逐水爱山春，两岸桃花夹古津。",
    "儿童相见不相识，笑问客从何处来。"
   ],
   "answer": 3,
   "themes": [
    "farewell",
    "homeland"
   ]
