   "title": "送杜少府之任蜀州",
   "author": "王勃",
   "fact": "王勃(650—676),唐代诗人。字子安，初唐四杰之一。他才华横溢，六岁能文，十四岁即以《滕王阁序》名动天下。可惜英年早逝，年仅二十六岁便溺水而亡。其诗雄浑壮阔，《送杜少府之任蜀州》是送别诗中的名篇。代表作:《送杜少府之任蜀州》《滕王阁序》。",
