   "author": "岑参",
   "fact": "岑参(715—770),唐代诗人。唐代边塞诗人，与高适并称「高岑」。他两度出塞，诗作多描写边塞风光和军旅生活，风格雄奇瑰丽，想象丰富，《白雪歌送武判官归京》是其代表作。代表作:《白雪歌送武判官归京》《逢入京使》《走马川行奉送封大夫出师西征》。",
