   "author": "李白",
   "fact": "李白(701—762),唐代诗人。字太白，号青莲居士，唐代伟大的浪漫主义诗人，被誉为「诗仙」。他豪放不羁、想象丰富，诗风雄奇飘逸。其诗常充满对自由的向往和对人生的热爱，代表作有《静夜思》《将进酒》《蜀道难》等。代表作:《静夜思》《将进酒》《蜀道难》《早发白帝城》《望庐山瀑布》。",
