   "title": "旅宿",
   "author": "杜牧",
   "fact": "杜牧(803—852),唐代诗人。字牧之，号樊川居士，晚唐杰出诗人。他的诗风格俊爽明快，七绝尤为出色，与李商隐并称「小李杜」。杜牧多才多艺，诗、赋、散文均有很高成就。代表作:《山行》《清明》《江南春》《泊船瓜洲》《赤壁》。",
