   "title": "蜀先主庙",
   "author": "刘禹锡",
   "fact": "刘禹锡(772—842),唐代诗人。字梦得，唐代诗人、文学家，与白居易并称「刘白」。他性格刚毅，诗风豪迈，《陋室铭》《竹枝词》等作品流传千古。即使身处逆境，仍保持乐观旷达的精神。代表作:《陋室铭》《望洞庭》《竹枝词》《秋词》。",
