   "title": "渭川田家",
   "author": "王维",
   "fact": "王维(701—761),唐代诗人。字摩诘，号摩诘居士，唐代山水田园诗派代表人物，被誉为「诗佛」。他的诗「诗中有画，画中有诗」，意境空灵淡远。苏轼评价他「味摩诘之诗，诗中有画；观摩诘之画，画中有诗」。代表作:《鸟鸣涧》《山居秋暝》《使至塞上》《送元二使安西》《九月九日忆山东兄弟》。",
