   "fact": "孟郊(751—814),唐代诗人。字东野，唐代诗人，以苦吟著称。他的诗多写世态炎凉和民间疾苦，语言质朴凝练，与贾岛并称「郊寒岛瘦」，与韩愈交好，韩愈评价其诗「横空盘硬语，妥帖力排奡」。代表作:《游子吟》《登科后》《苦寒吟》。",
