   "fact": "李商隐(813—858),唐代诗人。字义山，号玉溪生，晚唐著名诗人。他的诗构思新奇，风格浓丽，尤其是爱情诗写得深情绵邈、婉约含蓄，与杜牧合称「小李杜」，在中国诗歌史上占有重要地位。代表作:《夜雨寄北》《无题》《锦瑟》《登乐游原》。",
