   "fact": "纳兰性德(1655—1685),清代诗人。字容若，号楞伽山人，清代著名词人，权相明珠之子。他出身显贵却性情纯真，词作清新婉约，情感真挚动人，是清代词坛最杰出的作家之一，有「满清第一词人」之称。代表作:《长相思》《木兰花令》《蝶恋花》。",
