   "fact": "于谦(1398—1457),明代诗人。字廷益，号节庵，明代著名政治家、军事家、诗人。他为官清廉，刚正不阿，土木堡之变后力主抗敌，拥立景帝。《石灰吟》是他人格的写照。代表作:《石灰吟》《北风吹》《暮春阻雨》。",
